from sqlalchemy.inspection import inspect
from zou.app.utils.fields import serialize_value


class SerializerMixin(object):

    @classmethod
    def serialize(cls):
        attrs = inspect(cls).attrs.keys()
        return {
            "type": cls.__tablename__,
            **{ attr: serialize_value(getattr(cls, attr)) for attr in attrs }
        }

    @staticmethod
    def serialize_list(models):
        return [model.serialize() for model in models]

