class Node(object):
    def __eq__(self, other):
        return (
            self.__class__ == other.__class__ and
            self.__dict__ == other.__dict__
        )

    def __ne__(self, other):
        return not self == other


class App(Command):
    def execute(self):
        try:
            self.manager.execute(self)
        except AbortExecution, e:
            console.verbose = True
            log = [u'Execution aborted', u'']
            if e.message:
                log.append('%s' % e.message)
            console.write('\n'.join(log))
        except Exception, e:
            console.verbose = True
            config.show_traceback = True
            raise e


class Command(Node):
    def __init__(self, package=None, action=None):
        # TODO: Create a validator for that
        if package is None:
            if action is not None:
                raise ValueError(
                    "A command needs a package and an action"
                )
        elif action is None:
            action = package

        self.package = package
        self.action = action

    def __call__(self):
        if hasattr(self, 'execute'):
            return self.execute()


