    def __init__(self, name, value, help=None):
        self.name = name
        self.value = value
        self.help = help

    def __eq__(self, other):
        # TODO: Implement the help validation
        return (
            self.__class__ == other.__class__ and
            self.name == other.name and
            self.value == other.value
        )


